    },
  });
  if (data?.verified) {
    onVerifySuccess();   // proceed with edit
  } else {
    setError(data?.error ?? 'Verification failed.');
  }
};
```

---

### ❌ Problem 2 — `DriverDashboard`: `transferReconApi.requestEdit` doesn't call Edge Functions

`handleTransferEditRequest` calls `transferReconApi.requestEdit(id, reason)` which presumably writes `edit_request_status = 'pending'` to Supabase locally — but **never fires `send-otp-email`** to notify the admin. The OTP loop is completely missing.

The intended flow should be:

```
Driver clicks "Request Edit" → 
  1. Update transfer_recon_sheets.edit_request_status = 'pending'
  2. Call send-otp-email with resource_type='transfer_recon_edit', resource_id=sheet.id
  3. Admin receives email with OTP
  4. Admin opens AdminDashboard, sees pending request, enters OTP
  5. verify-otp called → on success, edit_request_status = 'approved'
  6. Driver can now edit the submitted sheet
```

**Fix for `handleTransferEditRequest`:**

```tsx
const handleTransferEditRequest = async (id: string, reason: string) => {
  // 1. Mark as pending in DB
  const { error: updateError } = await supabase
    .from('transfer_recon_sheets')
    .update({
      edit_request_status: 'pending',
      edit_request_reason: reason,
      edit_request_sent_at: new Date().toISOString(),
    })
    .eq('id', id);

  if (updateError) {
    alert('Failed to submit edit request.');
    return;
  }

  // 2. Trigger OTP email to admin
  const { error: otpError } = await supabase.functions.invoke('send-otp-email', {
    body: {
      resource_type: 'transfer_recon_edit',
      resource_id: id,                     // UUID of the transfer_recon_sheet
      context_label: `Transfer Recon Edit Request — ${driver.name}`,
    },
  });

  if (otpError) {
    alert('Edit request submitted, but failed to notify admin by email.');
  } else {
    alert('📩 Edit request submitted. Admin will receive a verification code to approve.');
  }

  refreshData();
};
```

---

### ❌ Problem 3 — Admin side has no UI to *approve* transfer recon edit requests with OTP

The admin needs a panel to see pending `transfer_recon_edit` requests and verify them. In `AdminDashboard`, add an approval flow:

```tsx
const handleApproveTransferReconEdit = (sheet: TransferReconSheet) => {
  executeWithOtpGuard(
    'transfer_recon_edit',
    sheet.id,                             // UUID — correct for resource_id
    async () => {
      await supabase
        .from('transfer_recon_sheets')
        .update({
          edit_request_status: 'approved',
          edit_request_approved_by: currentUser.id,
          edit_request_approved_at: new Date().toISOString(),
        })
        .eq('id', sheet.id);
      refreshData();
    },
    `Approve edit request from driver ${sheet.driver_id}`,
    true  // forceOtp: always require OTP for this action
  );
};
```

The `OTPModal` invocation already exists in `AdminDashboard` — this just needs to be wired up the same way `booking_edit` is.

---

### Summary of all changes

| File | Change |
|---|---|
| `OTPModal.tsx` | Add `send-otp-email` call on mount/open; add `verify-otp` call on code submit |
| `AdminDashboard.tsx` | Pass `booking.id` (UUID) not `booking.invoice_no` as `resourceId`; add `handleApproveTransferReconEdit` + UI panel for pending transfer recon requests |
| `DriverDashboard.tsx` | Replace `transferReconApi.requestEdit()` stub with real Supabase update + `send-otp-email` invoke |
| Schema | **No changes needed** — both resource types already exist in the constraint |

---

### One extra thing to verify

The `send-otp-email` function inserts into `otp_verifications` with `admin_id NOT NULL` — but when a *driver* triggers a transfer recon edit request, there's no `admin_id` to pass (it's the driver making the call). Your schema has `admin_id uuid NOT NULL` on that table. You have two options:

- **Option A:** Make `admin_id` nullable for `transfer_recon_edit` type rows (a small schema migration), OR
- **Option B:** In the driver's call to `send-otp-email`, look up and pass the admin's UUID server-side in the Edge Function (since it has service role access).

Option B is cleaner and keeps the constraint intact — the Edge Function can query `profiles` where `role = 'admin'` and use that `id`.

