  2173	export function getDocumentUrl(doc: any): string {
  2174	  if (!doc) return '';
  2175	  if (typeof doc === 'string') return doc;
  2176	  
  2177	  // Normalizes objects that look like stringified values or custom models
  2178	  if (doc.url && typeof doc.url === 'string') return doc.url;
  2179	  if (doc.secure_url && typeof doc.secure_url === 'string') return doc.secure_url;
  2180	
  2181	  // Handle spread objects, i.e., {"0":"h","1":"t", ...}
  2182	  if (typeof doc === 'object') {
  2183	    const keys = Object.keys(doc).sort((a, b) => Number(a) - Number(b));
  2184	    if (keys.length > 0 && keys.every(k => !isNaN(Number(k)))) {
  2185	      return keys.map(k => doc[k]).join('');
  2186	    }
  2187	  }
  2188	  return '';
  2189	}
