/* =====================================================================
   DEREK'S ROOFING — main.js
   Mobile nav, lightbox gallery, testimonial slider, FAQ accordion
   ===================================================================== */

document.addEventListener("DOMContentLoaded", function () {

  /* ---------- Mobile nav toggle ---------- */
  var toggle = document.querySelector(".nav-toggle");
  var nav = document.querySelector(".main-nav");
  if (toggle && nav) {
    toggle.addEventListener("click", function () {
      nav.classList.toggle("open");
    });
  }

  /* ---------- Active nav link ---------- */
  var current = window.location.pathname.split("/").pop() || "index.html";
  document.querySelectorAll(".main-nav a").forEach(function (link) {
    var href = link.getAttribute("href");
    if (href === current || (current === "" && href === "index.html")) {
      link.classList.add("active");
    }
  });

  /* ---------- Lightbox ---------- */
  var galleryItems = Array.prototype.slice.call(document.querySelectorAll("[data-lightbox]"));
  if (galleryItems.length) {
    var lightbox = document.createElement("div");
    lightbox.className = "lightbox";
    lightbox.innerHTML =
      '<button class="lightbox-close" aria-label="Close">&times;</button>' +
      '<button class="lightbox-prev" aria-label="Previous">&#8249;</button>' +
      '<img src="" alt="">' +
      '<button class="lightbox-next" aria-label="Next">&#8250;</button>';
    document.body.appendChild(lightbox);

    var lbImg = lightbox.querySelector("img");
    var currentIndex = 0;

    function openLightbox(index) {
      currentIndex = index;
      var el = galleryItems[index];
      lbImg.src = el.getAttribute("href") || el.getAttribute("data-full") || el.querySelector("img").src;
      lbImg.alt = el.querySelector("img") ? el.querySelector("img").alt : "";
      lightbox.classList.add("open");
    }
    function closeLightbox() { lightbox.classList.remove("open"); }
    function showNext() { openLightbox((currentIndex + 1) % galleryItems.length); }
    function showPrev() { openLightbox((currentIndex - 1 + galleryItems.length) % galleryItems.length); }

    galleryItems.forEach(function (el, i) {
      el.addEventListener("click", function (e) {
        e.preventDefault();
        openLightbox(i);
      });
    });

    lightbox.querySelector(".lightbox-close").addEventListener("click", closeLightbox);
    lightbox.querySelector(".lightbox-next").addEventListener("click", showNext);
    lightbox.querySelector(".lightbox-prev").addEventListener("click", showPrev);
    lightbox.addEventListener("click", function (e) {
      if (e.target === lightbox) closeLightbox();
    });
    document.addEventListener("keydown", function (e) {
      if (!lightbox.classList.contains("open")) return;
      if (e.key === "Escape") closeLightbox();
      if (e.key === "ArrowRight") showNext();
      if (e.key === "ArrowLeft") showPrev();
    });
  }

  /* ---------- Testimonial slider ---------- */
  var cards = Array.prototype.slice.call(document.querySelectorAll(".testimonial-card"));
  var dotsWrap = document.querySelector(".testimonial-dots");
  if (cards.length) {
    var tIndex = 0;
    cards.forEach(function (c, i) {
      var dot = document.createElement("button");
      if (i === 0) dot.classList.add("active");
      dot.setAttribute("aria-label", "Show testimonial " + (i + 1));
      dot.addEventListener("click", function () { showTestimonial(i); });
      if (dotsWrap) dotsWrap.appendChild(dot);
    });
    var dots = dotsWrap ? Array.prototype.slice.call(dotsWrap.querySelectorAll("button")) : [];

    function showTestimonial(i) {
      cards[tIndex].classList.remove("active");
      if (dots[tIndex]) dots[tIndex].classList.remove("active");
      tIndex = i;
      cards[tIndex].classList.add("active");
      if (dots[tIndex]) dots[tIndex].classList.add("active");
    }

    setInterval(function () {
      showTestimonial((tIndex + 1) % cards.length);
    }, 6000);
  }

  /* ---------- FAQ accordion ---------- */
  document.querySelectorAll(".accordion-item").forEach(function (item) {
    var q = item.querySelector(".accordion-q");
    var a = item.querySelector(".accordion-a");
    q.addEventListener("click", function () {
      var isOpen = item.classList.contains("open");
      document.querySelectorAll(".accordion-item.open").forEach(function (openItem) {
        if (openItem !== item) {
          openItem.classList.remove("open");
          openItem.querySelector(".accordion-a").style.maxHeight = null;
        }
      });
      if (isOpen) {
        item.classList.remove("open");
        a.style.maxHeight = null;
      } else {
        item.classList.add("open");
        a.style.maxHeight = a.scrollHeight + "px";
      }
    });
  });

  /* ---------- Simple client-side contact form validation (static version) ---------- */
  var contactForm = document.querySelector("#contactForm");
  if (contactForm && contactForm.dataset.staticForm === "true") {
    contactForm.addEventListener("submit", function () {
      // Formspree (or similar) handles the POST; nothing else needed here.
      // This block is a hook if you want to add client-side validation later.
    });
  }
});

