// netlify/functions/utils/sheets.js
// Thin wrapper around the Google Sheets API used as our "database".
//
// Sheet layout expected (see README for full setup steps):
//
// Tab "Products"  -> A:id | B:name | C:ml | D:description | E:price | F:stock
// Tab "Orders"     -> A:orderId | B:timestamp | C:customerName | D:email | E:phone
//                     | F:address | G:items(JSON) | H:total | I:paymentFrom
//                     | J:paymentTo | K:status

const { google } = require("googleapis");

const PRODUCTS_RANGE = "Products!A2:F";
const PRODUCTS_HEADER_ROW = "Products!A1:F1";
const ORDERS_RANGE = "Orders!A2:K";
const ORDERS_HEADER_ROW = "Orders!A1:K1";

function getAuth() {
  const email = process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL;
  const rawKey = process.env.GOOGLE_PRIVATE_KEY || "";
  const key = rawKey.replace(/\\n/g, "\n");

  if (!email || !key) {
    throw new Error(
      "Missing GOOGLE_SERVICE_ACCOUNT_EMAIL or GOOGLE_PRIVATE_KEY environment variables."
    );
  }

  return new google.auth.JWT(email, null, key, [
    "https://www.googleapis.com/auth/spreadsheets",
  ]);
}

async function getClient() {
  const auth = getAuth();
  await auth.authorize();
  return google.sheets({ version: "v4", auth });
}

function sheetId() {
  const id = process.env.GOOGLE_SHEET_ID;
  if (!id) throw new Error("Missing GOOGLE_SHEET_ID environment variable.");
  return id;
}

// Ensure header rows exist (safe to call often; it just rewrites them)
async function ensureHeaders(sheets) {
  await sheets.spreadsheets.values.update({
    spreadsheetId: sheetId(),
    range: PRODUCTS_HEADER_ROW,
    valueInputOption: "RAW",
    requestBody: {
      values: [["id", "name", "ml", "description", "price", "stock"]],
    },
  });
  await sheets.spreadsheets.values.update({
    spreadsheetId: sheetId(),
    range: ORDERS_HEADER_ROW,
    valueInputOption: "RAW",
    requestBody: {
      values: [
        [
          "orderId",
          "timestamp",
          "customerName",
          "email",
          "phone",
          "address",
          "items",
          "total",
          "paymentFrom",
          "paymentTo",
          "status",
        ],
      ],
    },
  });
}

async function getProducts() {
  const sheets = await getClient();
  const res = await sheets.spreadsheets.values.get({
    spreadsheetId: sheetId(),
    range: PRODUCTS_RANGE,
  });
  const rows = res.data.values || [];
  return rows
    .map((row, idx) => ({
      rowNumber: idx + 2, // actual row number in the sheet (header is row 1)
      id: row[0] || "",
      name: row[1] || "",
      ml: row[2] || "",
      description: row[3] || "",
      price: parseFloat(row[4]) || 0,
      stock: parseInt(row[5], 10) || 0,
    }))
    .filter((p) => p.id);
}

async function addProduct(product) {
  const sheets = await getClient();
  await sheets.spreadsheets.values.append({
    spreadsheetId: sheetId(),
    range: PRODUCTS_RANGE,
    valueInputOption: "RAW",
    insertDataOption: "INSERT_ROWS",
    requestBody: {
      values: [
        [
          product.id,
          product.name,
          product.ml,
          product.description,
          product.price,
          product.stock,
        ],
      ],
    },
  });
}

async function updateProductRow(rowNumber, product) {
  const sheets = await getClient();
  await sheets.spreadsheets.values.update({
    spreadsheetId: sheetId(),
    range: `Products!A${rowNumber}:F${rowNumber}`,
    valueInputOption: "RAW",
    requestBody: {
      values: [
        [
          product.id,
          product.name,
          product.ml,
          product.description,
          product.price,
          product.stock,
        ],
      ],
    },
  });
}

async function deleteProductRow(rowNumber) {
  const sheets = await getClient();
  // Find the actual sheetId (gid) of the "Products" tab
  const meta = await sheets.spreadsheets.get({ spreadsheetId: sheetId() });
  const tab = meta.data.sheets.find(
    (s) => s.properties.title === "Products"
  );
  if (!tab) throw new Error('Could not find a tab named "Products"');
  const gid = tab.properties.sheetId;

  await sheets.spreadsheets.batchUpdate({
    spreadsheetId: sheetId(),
    requestBody: {
      requests: [
        {
          deleteDimension: {
            range: {
              sheetId: gid,
              dimension: "ROWS",
              startIndex: rowNumber - 1, // 0-indexed
              endIndex: rowNumber,
            },
          },
        },
      ],
    },
  });
}

async function appendOrder(order) {
  const sheets = await getClient();
  await sheets.spreadsheets.values.append({
    spreadsheetId: sheetId(),
    range: ORDERS_RANGE,
    valueInputOption: "RAW",
    insertDataOption: "INSERT_ROWS",
    requestBody: {
      values: [
        [
          order.orderId,
          order.timestamp,
          order.customerName,
          order.email,
          order.phone,
          order.address,
          JSON.stringify(order.items),
          order.total,
          order.paymentFrom,
          order.paymentTo,
          order.status,
        ],
      ],
    },
  });
}

async function getOrders() {
  const sheets = await getClient();
  const res = await sheets.spreadsheets.values.get({
    spreadsheetId: sheetId(),
    range: ORDERS_RANGE,
  });
  const rows = res.data.values || [];
  return rows
    .map((row) => ({
      orderId: row[0] || "",
      timestamp: row[1] || "",
      customerName: row[2] || "",
      email: row[3] || "",
      phone: row[4] || "",
      address: row[5] || "",
      items: (() => {
        try {
          return JSON.parse(row[6] || "[]");
        } catch (e) {
          return [];
        }
      })(),
      total: parseFloat(row[7]) || 0,
      paymentFrom: row[8] || "",
      paymentTo: row[9] || "",
      status: row[10] || "",
    }))
    .filter((o) => o.orderId)
    .reverse(); // newest first
}

module.exports = {
  getClient,
  ensureHeaders,
  getProducts,
  addProduct,
  updateProductRow,
  deleteProductRow,
  appendOrder,
  getOrders,
};

