              endIndex: rowNumber,
            },
          },
        },
      ],
    },
  });
}

async function appendOrder(order) {
  const sheets = await getClient();
  await sheets.spreadsheets.values.append({
    spreadsheetId: sheetId(),
    range: ORDERS_RANGE,
    valueInputOption: "RAW",
    insertDataOption: "INSERT_ROWS",
    requestBody: {
      values: [
        [
          order.orderId,
          order.timestamp,
          order.customerName,
          order.email,
          order.phone,
          order.address,
          JSON.stringify(order.items),
          order.total,
          order.paymentFrom,
          order.paymentTo,
          order.status,
        ],
      ],
    },
  });
}

async function getOrders() {
  const sheets = await getClient();
  const res = await sheets.spreadsheets.values.get({
    spreadsheetId: sheetId(),
    range: ORDERS_RANGE,
  });
  const rows = res.data.values || [];
  return rows
    .map((row) => ({
      orderId: row[0] || "",
      timestamp: row[1] || "",
      customerName: row[2] || "",
      email: row[3] || "",
      phone: row[4] || "",
      address: row[5] || "",
      items: (() => {
        try {
          return JSON.parse(row[6] || "[]");
        } catch (e) {
          return [];
        }
      })(),
      total: parseFloat(row[7]) || 0,
      paymentFrom: row[8] || "",
      paymentTo: row[9] || "",
      status: row[10] || "",
    }))
    .filter((o) => o.orderId)
    .reverse(); // newest first
}

module.exports = {
  getClient,
  ensureHeaders,
  getProducts,
  addProduct,
  updateProductRow,
  deleteProductRow,
  appendOrder,
  getOrders,
};
