// netlify/functions/utils/auth.js
// Very lightweight admin session tokens, signed with HMAC so we don't need
// a database or Netlify Identity. Token format: "<expiry>.<signature>"

const crypto = require("crypto");

const TOKEN_LIFETIME_MS = 1000 * 60 * 60 * 8; // 8 hours

function getSecret() {
  const secret = process.env.ADMIN_TOKEN_SECRET;
  if (!secret) {
    throw new Error("Missing ADMIN_TOKEN_SECRET environment variable.");
  }
  return secret;
}

function sign(value) {
  return crypto.createHmac("sha256", getSecret()).update(value).digest("hex");
}

function createToken() {
  const expiry = Date.now() + TOKEN_LIFETIME_MS;
  const signature = sign(String(expiry));
  return `${expiry}.${signature}`;
}

function verifyToken(token) {
  if (!token || typeof token !== "string" || !token.includes(".")) {
    return false;
  }
  const [expiryStr, signature] = token.split(".");
  const expiry = parseInt(expiryStr, 10);
  if (!expiry || Date.now() > expiry) return false;

  const expectedSignature = sign(expiryStr);
  // timing-safe compare
  const a = Buffer.from(signature || "");
  const b = Buffer.from(expectedSignature);
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

// Helper to pull the token out of the Authorization header of a Netlify
// function event ("Bearer <token>")
function getTokenFromEvent(event) {
  const header =
    (event.headers && (event.headers.authorization || event.headers.Authorization)) ||
    "";
  const match = header.match(/^Bearer\s+(.+)$/i);
  return match ? match[1] : null;
}

function requireAdmin(event) {
  const token = getTokenFromEvent(event);
  return verifyToken(token);
}

module.exports = { createToken, verifyToken, getTokenFromEvent, requireAdmin };

