// netlify/functions/utils/mailer.js
// Sends the "new order" notification email to the shop admin via SMTP.

const nodemailer = require("nodemailer");

function getTransporter() {
  const {
    SMTP_HOST,
    SMTP_PORT,
    SMTP_SECURE,
    SMTP_USER,
    SMTP_PASS,
  } = process.env;

  if (!SMTP_HOST || !SMTP_USER || !SMTP_PASS) {
    throw new Error(
      "Missing SMTP_HOST, SMTP_USER or SMTP_PASS environment variables."
    );
  }

  return nodemailer.createTransport({
    host: SMTP_HOST,
    port: parseInt(SMTP_PORT, 10) || 465,
    secure: SMTP_SECURE !== "false", // true for 465, false for 587
    auth: {
      user: SMTP_USER,
      pass: SMTP_PASS,
    },
  });
}

async function sendAdminOrderNotification(order) {
  const adminEmail = process.env.ADMIN_EMAIL;
  const fromEmail = process.env.FROM_EMAIL || process.env.SMTP_USER;
  const storeName = process.env.STORE_NAME || "Perfume Store";

  if (!adminEmail) {
    console.warn("ADMIN_EMAIL not set — skipping admin notification email.");
    return;
  }

  const itemsHtml = order.items
    .map(
      (it) =>
        `<tr>
          <td style="padding:6px 10px;border-bottom:1px solid #eee;">${it.name} (${it.ml}ml)</td>
          <td style="padding:6px 10px;border-bottom:1px solid #eee;text-align:center;">${it.qty}</td>
          <td style="padding:6px 10px;border-bottom:1px solid #eee;text-align:right;">R${(it.price * it.qty).toFixed(2)}</td>
        </tr>`
    )
    .join("");

  const html = `
    <div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;">
      <h2 style="color:#8a6d1f;">New Order Received — ${storeName}</h2>
      <p><strong>Order ID:</strong> ${order.orderId}</p>
      <p><strong>Customer:</strong> ${order.customerName}</p>
      <p><strong>Email:</strong> ${order.email}</p>
      <p><strong>Phone:</strong> ${order.phone}</p>
      <p><strong>Address:</strong> ${order.address || "—"}</p>
      <p><strong>Will pay between:</strong> ${order.paymentFrom} and ${order.paymentTo}</p>
      <table style="width:100%;border-collapse:collapse;margin-top:10px;">
        <thead>
          <tr style="background:#f5f0e1;">
            <th style="padding:6px 10px;text-align:left;">Item</th>
            <th style="padding:6px 10px;text-align:center;">Qty</th>
            <th style="padding:6px 10px;text-align:right;">Subtotal</th>
          </tr>
        </thead>
        <tbody>${itemsHtml}</tbody>
      </table>
      <h3 style="text-align:right;margin-top:10px;">Total Due: R${order.total.toFixed(2)}</h3>
      <p style="color:#777;font-size:13px;">This is an automated notification from your perfume store website.</p>
    </div>
  `;

  const transporter = getTransporter();
  await transporter.sendMail({
    from: `"${storeName}" <${fromEmail}>`,
    to: adminEmail,
    subject: `New Order #${order.orderId} — R${order.total.toFixed(2)}`,
    html,
  });
}

module.exports = { sendAdminOrderNotification };

