// netlify/functions/get-products.js
// Public endpoint — returns the current product/stock list for the storefront.

const { getProducts } = require("./utils/sheets");

exports.handler = async function (event) {
  if (event.httpMethod !== "GET") {
    return { statusCode: 405, body: "Method Not Allowed" };
  }

  try {
    const products = await getProducts();
    // Don't leak internal row numbers to the public storefront
    const publicProducts = products.map(({ rowNumber, ...rest }) => rest);

    return {
      statusCode: 200,
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ products: publicProducts }),
    };
  } catch (err) {
    console.error(err);
    return {
      statusCode: 500,
      body: JSON.stringify({ error: "Failed to load products." }),
    };
  }
};

