// netlify/functions/submit-order.js
// Public endpoint — validates stock, writes the order to the "Orders" sheet,
// decrements stock on the "Products" sheet, and emails the admin.

const { getProducts, updateProductRow, appendOrder } = require("./utils/sheets");
const { sendAdminOrderNotification } = require("./utils/mailer");

function generateOrderId() {
  const now = new Date();
  const stamp = now
    .toISOString()
    .replace(/[-:T.Z]/g, "")
    .slice(0, 14);
  const rand = Math.floor(Math.random() * 900 + 100);
  return `ORD-${stamp}-${rand}`;
}

exports.handler = async function (event) {
  if (event.httpMethod !== "POST") {
    return { statusCode: 405, body: "Method Not Allowed" };
  }

  let data;
  try {
    data = JSON.parse(event.body || "{}");
  } catch (e) {
    return { statusCode: 400, body: JSON.stringify({ error: "Invalid JSON." }) };
  }

  const { customerName, email, phone, address, items, paymentFrom, paymentTo } = data;

  if (!customerName || !email || !phone || !Array.isArray(items) || items.length === 0) {
    return {
      statusCode: 400,
      body: JSON.stringify({ error: "Missing required fields or empty cart." }),
    };
  }
  if (!paymentFrom || !paymentTo) {
    return {
      statusCode: 400,
      body: JSON.stringify({ error: "Please choose a payment date range." }),
    };
  }

  try {
    const products = await getProducts();
    const productsById = new Map(products.map((p) => [p.id, p]));

    // Validate stock + build authoritative order line items (never trust client-sent prices)
    const orderItems = [];
    for (const cartItem of items) {
      const product = productsById.get(cartItem.id);
      if (!product) {
        return {
          statusCode: 400,
          body: JSON.stringify({ error: `Product "${cartItem.id}" no longer exists.` }),
        };
      }
      const qty = parseInt(cartItem.qty, 10) || 0;
      if (qty <= 0) continue;
      if (qty > product.stock) {
        return {
          statusCode: 400,
          body: JSON.stringify({
            error: `Sorry, only ${product.stock} unit(s) of "${product.name}" left in stock.`,
          }),
        };
      }
      orderItems.push({
        id: product.id,
        name: product.name,
        ml: product.ml,
        price: product.price,
        qty,
      });
    }

    if (orderItems.length === 0) {
      return { statusCode: 400, body: JSON.stringify({ error: "Cart is empty." }) };
    }

    const total = orderItems.reduce((sum, it) => sum + it.price * it.qty, 0);

    const order = {
      orderId: generateOrderId(),
      timestamp: new Date().toISOString(),
      customerName,
      email,
      phone,
      address: address || "",
      items: orderItems,
      total,
      paymentFrom,
      paymentTo,
      status: "Pending Payment",
    };

    // 1. Save the order
    await appendOrder(order);

    // 2. Decrement stock for each purchased product
    for (const orderItem of orderItems) {
      const product = productsById.get(orderItem.id);
      const newStock = Math.max(0, product.stock - orderItem.qty);
      await updateProductRow(product.rowNumber, { ...product, stock: newStock });
    }

    // 3. Notify admin (don't fail the order if email sending has an issue)
    try {
      await sendAdminOrderNotification(order);
    } catch (mailErr) {
      console.error("Failed to send admin notification email:", mailErr);
    }

    return {
      statusCode: 200,
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ success: true, order }),
    };
  } catch (err) {
    console.error(err);
    return {
      statusCode: 500,
      body: JSON.stringify({ error: "Something went wrong while placing your order." }),
    };
  }
};

