// netlify/functions/admin-login.js
// Checks the password the admin typed against ADMIN_PASSWORD and, if correct,
// returns a signed session token used by the other admin-* functions.

const { createToken } = require("./utils/auth");

exports.handler = async function (event) {
  if (event.httpMethod !== "POST") {
    return { statusCode: 405, body: "Method Not Allowed" };
  }

  let data;
  try {
    data = JSON.parse(event.body || "{}");
  } catch (e) {
    return { statusCode: 400, body: JSON.stringify({ error: "Invalid JSON." }) };
  }

  const { password } = data;
  const correctPassword = process.env.ADMIN_PASSWORD;

  if (!correctPassword) {
    return {
      statusCode: 500,
      body: JSON.stringify({ error: "Server is missing ADMIN_PASSWORD configuration." }),
    };
  }

  if (password !== correctPassword) {
    return {
      statusCode: 401,
      body: JSON.stringify({ error: "Incorrect password." }),
    };
  }

  const token = createToken();
  return {
    statusCode: 200,
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ success: true, token }),
  };
};

