// netlify/functions/admin-products.js
// Protected endpoint (requires a valid admin token) for managing the product
// catalogue: add new perfumes, edit details, adjust/add stock, or delete.
//
// Expected POST body: { action, product, ... } — see each case below.

const { requireAdmin } = require("./utils/auth");
const {
  getProducts,
  addProduct,
  updateProductRow,
  deleteProductRow,
} = require("./utils/sheets");

function generateProductId(name) {
  const slug = (name || "perfume")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
  return `${slug}-${Date.now().toString(36)}`;
}

exports.handler = async function (event) {
  if (event.httpMethod !== "POST") {
    return { statusCode: 405, body: "Method Not Allowed" };
  }

  if (!requireAdmin(event)) {
    return { statusCode: 401, body: JSON.stringify({ error: "Unauthorized." }) };
  }

  let data;
  try {
    data = JSON.parse(event.body || "{}");
  } catch (e) {
    return { statusCode: 400, body: JSON.stringify({ error: "Invalid JSON." }) };
  }

  const { action } = data;

  try {
    if (action === "list") {
      const products = await getProducts();
      return ok({ products });
    }

    if (action === "create") {
      const { name, ml, description, price, stock } = data.product || {};
      if (!name || price === undefined) {
        return badRequest("Name and price are required.");
      }
      const newProduct = {
        id: generateProductId(name),
        name,
        ml: ml || "",
        description: description || "",
        price: parseFloat(price) || 0,
        stock: parseInt(stock, 10) || 0,
      };
      await addProduct(newProduct);
      return ok({ product: newProduct });
    }

    if (action === "update") {
      const { id, name, ml, description, price, stock } = data.product || {};
      if (!id) return badRequest("Missing product id.");

      const products = await getProducts();
      const existing = products.find((p) => p.id === id);
      if (!existing) return badRequest("Product not found.");

      const updated = {
        id,
        name: name ?? existing.name,
        ml: ml ?? existing.ml,
        description: description ?? existing.description,
        price: price !== undefined ? parseFloat(price) : existing.price,
        stock: stock !== undefined ? parseInt(stock, 10) : existing.stock,
      };
      await updateProductRow(existing.rowNumber, updated);
      return ok({ product: updated });
    }

    if (action === "adjustStock") {
      // amount can be positive (add stock in) or negative (remove/correct)
      const { id, amount } = data;
      if (!id || amount === undefined) return badRequest("Missing id or amount.");

      const products = await getProducts();
      const existing = products.find((p) => p.id === id);
      if (!existing) return badRequest("Product not found.");

      const newStock = Math.max(0, existing.stock + parseInt(amount, 10));
      const updated = { ...existing, stock: newStock };
      await updateProductRow(existing.rowNumber, updated);
      return ok({ product: updated });
    }

    if (action === "delete") {
      const { id } = data;
      if (!id) return badRequest("Missing product id.");

      const products = await getProducts();
      const existing = products.find((p) => p.id === id);
      if (!existing) return badRequest("Product not found.");

      await deleteProductRow(existing.rowNumber);
      return ok({ deleted: id });
    }

    return badRequest(`Unknown action "${action}".`);
  } catch (err) {
    console.error(err);
    return {
      statusCode: 500,
      body: JSON.stringify({ error: "Server error managing products." }),
    };
  }
};

function ok(body) {
  return {
    statusCode: 200,
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ success: true, ...body }),
  };
}

function badRequest(message) {
  return { statusCode: 400, body: JSON.stringify({ error: message }) };
}

