/* ============================================================
   PERFUME STORE — STYLESHEET
   Design tokens: warm boutique palette, serif/sans type pairing
   ============================================================ */

:root {
  /* Color tokens */
  --ink: #221d18;
  --ink-soft: #4a4138;
  --cream: #f6f0e4;
  --cream-deep: #efe6d2;
  --gold: #b8924a;
  --gold-light: #e7d7b1;
  --gold-dark: #8f6f33;
  --wine: #5b1f29;
  --wine-light: #7a2e3b;
  --line: #d9cdb5;
  --white: #fffdf9;
  --success: #3f6b3f;
  --error: #8a2e2e;

  /* Type */
  --font-display: "Cormorant Garamond", "Times New Roman", serif;
  --font-body: "Jost", "Helvetica Neue", Arial, sans-serif;

  /* Spacing scale */
  --space-1: 0.4rem;
  --space-2: 0.8rem;
  --space-3: 1.4rem;
  --space-4: 2.2rem;
  --space-5: 3.6rem;
  --space-6: 5.6rem;

  --radius: 2px;
  --shadow-soft: 0 10px 30px rgba(34, 29, 24, 0.08);
  --shadow-lift: 0 16px 40px rgba(34, 29, 24, 0.16);
  --max-width: 1180px;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  background: var(--cream);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }

a { color: inherit; text-decoration: none; }

h1, h2, h3, h4 {
  font-family: var(--font-display);
  font-weight: 600;
  margin: 0 0 var(--space-2);
  color: var(--ink);
  letter-spacing: 0.01em;
}

p { margin: 0 0 var(--space-2); }

.eyebrow {
  font-family: var(--font-body);
  font-size: 0.72rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold-dark);
  font-weight: 500;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-4);
}

button {
  font-family: var(--font-body);
  cursor: pointer;
  border: none;
  background: none;
}

button:focus-visible,
a:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 2px solid var(--gold-dark);
  outline-offset: 2px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5em;
  padding: 0.85rem 1.8rem;
  font-size: 0.85rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 500;
  border-radius: var(--radius);
  transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.btn-primary {
  background: var(--ink);
  color: var(--cream);
}
.btn-primary:hover { background: var(--wine); box-shadow: var(--shadow-soft); }

.btn-outline {
  background: transparent;
  color: var(--ink);
  border: 1px solid var(--ink);
}
.btn-outline:hover { background: var(--ink); color: var(--cream); }

.btn-gold {
  background: var(--gold);
  color: var(--ink);
}
.btn-gold:hover { background: var(--gold-dark); color: var(--white); }

.btn:disabled { opacity: 0.45; cursor: not-allowed; transform: none !important; }

.btn-block { width: 100%; }

/* ============================== HEADER ============================== */

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(246, 240, 228, 0.92);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--line);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-2) var(--space-4);
  max-width: var(--max-width);
  margin: 0 auto;
}

.brand {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.brand-name {
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 600;
  letter-spacing: 0.02em;
}

/* Signature wax-seal monogram */
.seal {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 1.5px solid var(--gold);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  flex-shrink: 0;
}
.seal::before {
  content: "";
  position: absolute;
  inset: 5px;
  border-radius: 50%;
  border: 1px solid var(--gold);
  opacity: 0.5;
}
.seal span {
  font-family: var(--font-display);
  font-size: 1rem;
  color: var(--gold-dark);
  font-weight: 600;
}

.cart-trigger {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--space-1);
  font-size: 0.78rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0.6rem 1rem;
  border: 1px solid var(--ink);
  border-radius: var(--radius);
}
.cart-trigger:hover { background: var(--ink); color: var(--cream); }

.cart-count {
  background: var(--wine);
  color: var(--white);
  border-radius: 50%;
  min-width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 600;
}

/* ============================== HERO ============================== */

.hero {
  position: relative;
  overflow: hidden;
  border-bottom: 1px solid var(--line);
}

.hero-inner {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  align-items: center;
  gap: var(--space-5);
  padding: var(--space-6) var(--space-4);
  max-width: var(--max-width);
  margin: 0 auto;
}

.hero-copy h1 {
  font-size: clamp(2.4rem, 5vw, 3.8rem);
  line-height: 1.08;
  margin-bottom: var(--space-3);
}

.hero-copy p {
  max-width: 480px;
  color: var(--ink-soft);
  font-size: 1.05rem;
}

.hero-actions {
  display: flex;
  gap: var(--space-2);
  margin-top: var(--space-4);
  flex-wrap: wrap;
}

.hero-note {
  margin-top: var(--space-3);
  font-size: 0.82rem;
  color: var(--gold-dark);
  letter-spacing: 0.03em;
}

.hero-art {
  display: flex;
  justify-content: center;
  align-items: center;
}

.hero-art svg { width: 100%; max-width: 320px; }

.drip {
  animation: drip-fall 4.5s ease-in-out infinite;
  transform-origin: top center;
}
@keyframes drip-fall {
  0%, 100% { transform: translateY(0) scaleY(1); opacity: 0.9; }
  50% { transform: translateY(10px) scaleY(1.08); opacity: 0.55; }
}

/* ============================== PRODUCTS ============================== */

.section {
  padding: var(--space-5) 0;
}

.section-head {
  text-align: center;
  max-width: 560px;
  margin: 0 auto var(--space-5);
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-4);
}

.product-card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  display: flex;
  flex-direction: column;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}
.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lift);
}

.product-media {
  aspect-ratio: 1 / 1;
  background: linear-gradient(160deg, var(--cream-deep), var(--gold-light));
  display: flex;
  align-items: center;
  justify-content: center;
  border-bottom: 1px solid var(--line);
  position: relative;
}
.product-media svg { width: 42%; opacity: 0.85; }

.stock-tag {
  position: absolute;
  top: 10px;
  right: 10px;
  font-size: 0.65rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 0.25rem 0.6rem;
  border-radius: 20px;
  background: var(--white);
  border: 1px solid var(--line);
}
.stock-tag.low { color: var(--wine); border-color: var(--wine); }
.stock-tag.out { color: var(--white); background: var(--ink); border-color: var(--ink); }

.product-body {
  padding: var(--space-3);
  display: flex;
  flex-direction: column;
  flex: 1;
}

.product-name {
  font-size: 1.25rem;
  margin-bottom: 0.2rem;
}

.product-ml {
  font-size: 0.78rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--gold-dark);
  margin-bottom: var(--space-2);
}

.product-desc {
  color: var(--ink-soft);
  font-size: 0.9rem;
  flex: 1;
  margin-bottom: var(--space-3);
}

.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
}

.product-price {
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 600;
}

.qty-stepper {
  display: flex;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: var(--radius);
}
.qty-stepper button {
  width: 30px;
  height: 30px;
  font-size: 1rem;
  color: var(--ink);
}
.qty-stepper button:hover { background: var(--cream-deep); }
.qty-stepper span {
  width: 30px;
  text-align: center;
  font-size: 0.9rem;
}

.add-to-cart-row {
  display: flex;
  gap: var(--space-2);
  margin-top: var(--space-2);
}
.add-to-cart-row .btn { flex: 1; padding: 0.7rem 1rem; font-size: 0.75rem; }

.empty-state {
  text-align: center;
  padding: var(--space-5);
  color: var(--ink-soft);
  border: 1px dashed var(--line);
  border-radius: var(--radius);
}

/* ============================== CART DRAWER ============================== */

.overlay {
  position: fixed;
  inset: 0;
  background: rgba(34, 29, 24, 0.45);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
  z-index: 90;
}
.overlay.active { opacity: 1; pointer-events: auto; }

.cart-drawer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(420px, 100%);
  background: var(--cream);
  border-left: 1px solid var(--line);
  transform: translateX(100%);
  transition: transform 0.3s ease;
  z-index: 95;
  display: flex;
  flex-direction: column;
}
.cart-drawer.active { transform: translateX(0); }

.drawer-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-3) var(--space-4);
  border-bottom: 1px solid var(--line);
}

.icon-btn {
  width: 34px;
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  border-radius: 50%;
}
.icon-btn:hover { background: var(--cream-deep); }

.cart-items {
  flex: 1;
  overflow-y: auto;
  padding: var(--space-3) var(--space-4);
}

.cart-line {
  display: flex;
  justify-content: space-between;
  gap: var(--space-2);
  padding: var(--space-2) 0;
  border-bottom: 1px solid var(--line);
}

.cart-line-info { flex: 1; }
.cart-line-name { font-weight: 500; font-size: 0.95rem; }
.cart-line-meta { font-size: 0.78rem; color: var(--ink-soft); }
.cart-line-remove {
  font-size: 0.72rem;
  text-decoration: underline;
  color: var(--wine);
  margin-top: 0.3rem;
}

.drawer-foot {
  border-top: 1px solid var(--line);
  padding: var(--space-3) var(--space-4);
}

.cart-total-row {
  display: flex;
  justify-content: space-between;
  font-family: var(--font-display);
  font-size: 1.3rem;
  margin-bottom: var(--space-3);
}

/* ============================== MODAL (Checkout) ============================== */

.modal-wrap {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-3);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
  background: rgba(34, 29, 24, 0.5);
}
.modal-wrap.active { opacity: 1; pointer-events: auto; }

.modal {
  background: var(--white);
  max-width: 560px;
  width: 100%;
  max-height: 90vh;
  overflow-y: auto;
  border-radius: var(--radius);
  padding: var(--space-4);
  position: relative;
  box-shadow: var(--shadow-lift);
}

.modal-close {
  position: absolute;
  top: var(--space-2);
  right: var(--space-2);
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-2) var(--space-3);
  margin-top: var(--space-3);
}
.form-grid .full { grid-column: 1 / -1; }

label {
  display: block;
  font-size: 0.75rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--ink-soft);
  margin-bottom: 0.35rem;
}

input, textarea {
  width: 100%;
  font-family: var(--font-body);
  font-size: 0.95rem;
  padding: 0.65rem 0.8rem;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--cream);
  color: var(--ink);
}
input:focus, textarea:focus { border-color: var(--gold); }

.field-hint {
  font-size: 0.72rem;
  color: var(--ink-soft);
  margin-top: 0.3rem;
}

.form-msg {
  margin-top: var(--space-2);
