          event_label:     formData.service || 'general',
          value:           1,
          form_name:       'onedays-lead-form',
          service_type:    formData.service || 'not_specified',
          urgency_level:   formData.urgency || 'not_specified',
          suburb:          formData.suburb  || 'not_specified',
