-- ============================================================
-- Fhdan Fleet Hub — Enhanced Schema with Audit Logs & Advanced Features
-- Run this in: Supabase Dashboard → SQL Editor → New Query
-- ============================================================

-- Enums
CREATE TYPE user_role AS ENUM ('system_admin','manager','finance_officer','sales_agent','fleet_coordinator','driver');
CREATE TYPE client_type AS ENUM ('individual','corporate','government');
CREATE TYPE client_status AS ENUM ('active','inactive','blacklisted');
CREATE TYPE currency_code AS ENUM ('ZAR','USD','EUR','GBP','AED');
CREATE TYPE tax_zone AS ENUM ('standard','exempt','foreign');
CREATE TYPE vehicle_status AS ENUM ('available','booked','maintenance','inactive');
CREATE TYPE vehicle_category AS ENUM ('sedan','suv','luxury','minibus','bus','van','pickup');
CREATE TYPE drive_mode AS ENUM ('chauffeur','self_drive','both');
CREATE TYPE fuel_type AS ENUM ('petrol','diesel','electric','hybrid');
CREATE TYPE driver_status AS ENUM ('available','on_trip','off_duty','suspended');
CREATE TYPE license_code AS ENUM ('B','C','C1','EB','PDP');
CREATE TYPE booking_status AS ENUM ('quote','pending_deposit','confirmed','active','completed','cancelled','no_show');
CREATE TYPE booking_type AS ENUM ('chauffeur','self_drive');
CREATE TYPE invoice_status AS ENUM ('draft','sent','paid','overdue','cancelled','void');
CREATE TYPE payment_method AS ENUM ('eft','cash','card','crypto','other');
CREATE TYPE entity_type AS ENUM ('client','driver','vehicle');
CREATE TYPE document_type AS ENUM ('passport','rsa_id','drivers_license','pdp','vehicle_registration','insurance','roadworthy','other');
CREATE TYPE audit_action AS ENUM ('create','update','delete','login','logout','access_denied');
CREATE TYPE notification_type AS ENUM ('booking_confirmed','payment_received','deposit_reminder','late_return','maintenance_due','high_value_booking','system_alert');
CREATE TYPE notification_status AS ENUM ('pending','sent','failed');

-- ─── Profiles (extends auth.users) ───────────────────────────
CREATE TABLE public.profiles (
  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  email TEXT NOT NULL,
  full_name TEXT NOT NULL,
  role user_role NOT NULL DEFAULT 'sales_agent',
  phone TEXT,
  avatar_url TEXT,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  last_login TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Clients ─────────────────────────────────────────────────
CREATE TABLE public.clients (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email TEXT NOT NULL,
  full_name TEXT NOT NULL,
  phone TEXT,
  id_number TEXT,
  client_type client_type NOT NULL DEFAULT 'individual',
  status client_status NOT NULL DEFAULT 'active',
  company_name TEXT,
  vat_number TEXT,
  tax_zone tax_zone NOT NULL DEFAULT 'standard',
  preferred_currency currency_code NOT NULL DEFAULT 'ZAR',
  payment_terms_days INTEGER NOT NULL DEFAULT 30,
  address TEXT,
  city TEXT,
  country TEXT NOT NULL DEFAULT 'South Africa',
  notes TEXT,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Vehicles ────────────────────────────────────────────────
CREATE TABLE public.vehicles (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  registration TEXT NOT NULL UNIQUE,
  make TEXT NOT NULL,
  model TEXT NOT NULL,
  year INTEGER NOT NULL,
  color TEXT NOT NULL,
  category vehicle_category NOT NULL,
  fuel_type fuel_type NOT NULL DEFAULT 'petrol',
  seating_capacity INTEGER NOT NULL DEFAULT 4,
  drive_modes drive_mode NOT NULL DEFAULT 'both',
  status vehicle_status NOT NULL DEFAULT 'available',
  daily_rate_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  chauffeur_rate_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  odometer_km INTEGER NOT NULL DEFAULT 0,
  last_service_date DATE,
  next_service_due_km INTEGER,
  insurance_expiry DATE,
  roadworthy_expiry DATE,
  gps_tracker_id TEXT,
  current_latitude NUMERIC(10,6),
  current_longitude NUMERIC(10,6),
  last_gps_update TIMESTAMPTZ,
  image_url TEXT,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Drivers ─────────────────────────────────────────────────
CREATE TABLE public.drivers (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  full_name TEXT NOT NULL,
  phone TEXT NOT NULL,
  email TEXT,
  id_number TEXT,
  license_code license_code NOT NULL DEFAULT 'EB',
  pdp_expiry DATE,
  status driver_status NOT NULL DEFAULT 'available',
  total_trips INTEGER NOT NULL DEFAULT 0,
  current_latitude NUMERIC(10,6),
  current_longitude NUMERIC(10,6),
  last_location_update TIMESTAMPTZ,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Exchange Rates (for multi-currency quoting) ─────────────
CREATE TABLE public.exchange_rates (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  from_currency currency_code NOT NULL,
  to_currency currency_code NOT NULL,
  rate NUMERIC(12,6) NOT NULL,
  effective_date DATE NOT NULL DEFAULT CURRENT_DATE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(from_currency, to_currency, effective_date)
);

-- ─── Bookings ────────────────────────────────────────────────
CREATE TABLE public.bookings (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  booking_reference TEXT NOT NULL UNIQUE,
  client_id UUID NOT NULL REFERENCES public.clients(id),
  vehicle_id UUID NOT NULL REFERENCES public.vehicles(id),
  driver_id UUID REFERENCES public.drivers(id),
  assigned_by UUID REFERENCES public.profiles(id),
  booking_type booking_type NOT NULL DEFAULT 'chauffeur',
  status booking_status NOT NULL DEFAULT 'quote',
  pickup_datetime TIMESTAMPTZ NOT NULL,
  dropoff_datetime TIMESTAMPTZ NOT NULL,
  pickup_location TEXT NOT NULL,
  dropoff_location TEXT NOT NULL,
  currency TEXT NOT NULL DEFAULT 'ZAR',
  exchange_rate_id UUID REFERENCES public.exchange_rates(id),
  locked_exchange_rate NUMERIC(12,6),
  subtotal_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  discount_amount NUMERIC(10,2) NOT NULL DEFAULT 0,
  deposit_amount NUMERIC(10,2) NOT NULL DEFAULT 0,
  vat_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  total_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  special_requirements TEXT,
  internal_notes TEXT,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Invoices ────────────────────────────────────────────────
CREATE TABLE public.invoices (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_number TEXT NOT NULL UNIQUE,
  booking_id UUID NOT NULL REFERENCES public.bookings(id),
  client_id UUID NOT NULL REFERENCES public.clients(id),
  status invoice_status NOT NULL DEFAULT 'draft',
  subtotal_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  vat_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  total_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  balance_due_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  payments_received NUMERIC(10,2) NOT NULL DEFAULT 0,
  issued_date DATE NOT NULL DEFAULT CURRENT_DATE,
  due_date DATE NOT NULL,
  paid_date DATE,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Payments ────────────────────────────────────────────────
CREATE TABLE public.payments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id UUID NOT NULL REFERENCES public.invoices(id),
  amount_zar NUMERIC(10,2) NOT NULL,
  payment_method payment_method NOT NULL DEFAULT 'eft',
  payment_date DATE NOT NULL DEFAULT CURRENT_DATE,
  reference TEXT,
  notes TEXT,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Documents (with encryption metadata) ────────────────────
CREATE TABLE public.documents (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  entity_type entity_type NOT NULL,
  entity_id UUID NOT NULL,
  document_type document_type NOT NULL,
  file_name TEXT NOT NULL,
  file_path TEXT,
  file_size INTEGER NOT NULL DEFAULT 0,
  is_encrypted BOOLEAN NOT NULL DEFAULT TRUE,
  encryption_key_id TEXT,
  expiry_date DATE,
  uploaded_by UUID NOT NULL REFERENCES public.profiles(id),
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── IMMUTABLE Audit Log ──────────────────────────────────────
-- This table has NO UPDATE or DELETE policies - records are permanent
CREATE TABLE public.audit_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES public.profiles(id),
  user_email TEXT NOT NULL,
  user_role user_role,
  action audit_action NOT NULL,
  table_name TEXT NOT NULL,
  record_id UUID,
  old_data JSONB,
  new_data JSONB,
  ip_address TEXT,
  user_agent TEXT,
  timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Notifications ────────────────────────────────────────────
CREATE TABLE public.notifications (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  recipient_email TEXT NOT NULL,
  recipient_phone TEXT,
  notification_type notification_type NOT NULL,
  subject TEXT NOT NULL,
  message TEXT NOT NULL,
  status notification_status NOT NULL DEFAULT 'pending',
  related_booking_id UUID REFERENCES public.bookings(id),
  related_invoice_id UUID REFERENCES public.invoices(id),
  sent_at TIMESTAMPTZ,
  error_message TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Activity Timeline (for 360° history view) ───────────────
CREATE TABLE public.activity_timeline (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  entity_type entity_type NOT NULL,
  entity_id UUID NOT NULL,
  activity_type TEXT NOT NULL,
  description TEXT NOT NULL,
  metadata JSONB,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Auto-update updated_at ──────────────────────────────────
CREATE OR REPLACE FUNCTION update_updated_at()
RETURNS TRIGGER AS $$
BEGIN NEW.updated_at = NOW(); RETURN NEW; END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_profiles_updated_at BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER trg_clients_updated_at BEFORE UPDATE ON public.clients FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER trg_vehicles_updated_at BEFORE UPDATE ON public.vehicles FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER trg_drivers_updated_at BEFORE UPDATE ON public.drivers FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER trg_bookings_updated_at BEFORE UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER trg_invoices_updated_at BEFORE UPDATE ON public.invoices FOR EACH ROW EXECUTE FUNCTION update_updated_at();

-- ─── Auto-create profile on signup ──────────────────────────
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.profiles (id, email, full_name, role)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', split_part(NEW.email, '@', 1)),
    COALESCE((NEW.raw_user_meta_data->>'role')::user_role, 'sales_agent')
  );
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- ─── Audit Log Trigger Function ──────────────────────────────
CREATE OR REPLACE FUNCTION public.log_audit()
RETURNS TRIGGER AS $$
DECLARE
  current_user_email TEXT;
  current_user_role user_role;
  action_type audit_action;
BEGIN
  -- Get current user info
  SELECT email, role INTO current_user_email, current_user_role 
  FROM public.profiles WHERE id = auth.uid();

  -- Determine action type
  IF TG_OP = 'INSERT' THEN
    action_type := 'create';
  ELSIF TG_OP = 'UPDATE' THEN
    action_type := 'update';
  ELSIF TG_OP = 'DELETE' THEN
    action_type := 'delete';
  END IF;

  -- Insert audit log
  INSERT INTO public.audit_logs (
    user_id, user_email, user_role, action, table_name, 
    record_id, old_data, new_data, timestamp
  ) VALUES (
    auth.uid(),
    COALESCE(current_user_email, 'system'),
    current_user_role,
    action_type,
    TG_TABLE_NAME,
    COALESCE(NEW.id, OLD.id),
    CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN row_to_json(OLD) ELSE NULL END,
    CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN row_to_json(NEW) ELSE NULL END,
    NOW()
  );

  RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ─── Apply Audit Triggers to All Tables ──────────────────────
CREATE TRIGGER audit_clients AFTER INSERT OR UPDATE OR DELETE ON public.clients
  FOR EACH ROW EXECUTE FUNCTION public.log_audit();

CREATE TRIGGER audit_vehicles AFTER INSERT OR UPDATE OR DELETE ON public.vehicles
  FOR EACH ROW EXECUTE FUNCTION public.log_audit();

CREATE TRIGGER audit_drivers AFTER INSERT OR UPDATE OR DELETE ON public.drivers
  FOR EACH ROW EXECUTE FUNCTION public.log_audit();

CREATE TRIGGER audit_bookings AFTER INSERT OR UPDATE OR DELETE ON public.bookings
  FOR EACH ROW EXECUTE FUNCTION public.log_audit();

CREATE TRIGGER audit_invoices AFTER INSERT OR UPDATE OR DELETE ON public.invoices
  FOR EACH ROW EXECUTE FUNCTION public.log_audit();

CREATE TRIGGER audit_payments AFTER INSERT OR UPDATE OR DELETE ON public.payments
  FOR EACH ROW EXECUTE FUNCTION public.log_audit();

CREATE TRIGGER audit_documents AFTER INSERT OR UPDATE OR DELETE ON public.documents
  FOR EACH ROW EXECUTE FUNCTION public.log_audit();

-- ─── Activity Timeline Triggers ──────────────────────────────
CREATE OR REPLACE FUNCTION public.log_activity()
RETURNS TRIGGER AS $$
DECLARE
  activity_desc TEXT;
  entity_type_val entity_type;
BEGIN
  -- Determine entity type and description based on table
  IF TG_TABLE_NAME = 'bookings' THEN
    entity_type_val := 'client';
    IF TG_OP = 'INSERT' THEN
      activity_desc := 'New booking created: ' || NEW.booking_reference;
    ELSIF TG_OP = 'UPDATE' AND OLD.status != NEW.status THEN
      activity_desc := 'Booking status changed from ' || OLD.status || ' to ' || NEW.status;
    END IF;

    IF activity_desc IS NOT NULL THEN
      INSERT INTO public.activity_timeline (entity_type, entity_id, activity_type, description, metadata, created_by)
      VALUES (entity_type_val, NEW.client_id, 'booking', activity_desc, row_to_json(NEW), auth.uid());
    END IF;

  ELSIF TG_TABLE_NAME = 'invoices' AND TG_OP = 'INSERT' THEN
    INSERT INTO public.activity_timeline (entity_type, entity_id, activity_type, description, metadata, created_by)
    VALUES ('client', NEW.client_id, 'invoice', 'Invoice generated: ' || NEW.invoice_number, row_to_json(NEW), auth.uid());

  ELSIF TG_TABLE_NAME = 'payments' AND TG_OP = 'INSERT' THEN
    INSERT INTO public.activity_timeline (entity_type, entity_id, activity_type, description, metadata, created_by)
    VALUES ('client', (SELECT client_id FROM public.invoices WHERE id = NEW.invoice_id), 'payment', 
            'Payment received: R' || NEW.amount_zar, row_to_json(NEW), auth.uid());
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE TRIGGER activity_bookings AFTER INSERT OR UPDATE ON public.bookings
  FOR EACH ROW EXECUTE FUNCTION public.log_activity();

CREATE TRIGGER activity_invoices AFTER INSERT ON public.invoices
  FOR EACH ROW EXECUTE FUNCTION public.log_activity();

CREATE TRIGGER activity_payments AFTER INSERT ON public.payments
  FOR EACH ROW EXECUTE FUNCTION public.log_activity();

-- ─── Helper: get current user role ──────────────────────────
CREATE OR REPLACE FUNCTION public.get_user_role()
RETURNS user_role AS $$
  SELECT role FROM public.profiles WHERE id = auth.uid()
$$ LANGUAGE SQL SECURITY DEFINER STABLE;

-- ─── Enable RLS ──────────────────────────────────────────────
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.clients ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vehicles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.drivers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.bookings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.activity_timeline ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.exchange_rates ENABLE ROW LEVEL SECURITY;

-- ─── RLS Policies ────────────────────────────────────────────

-- Profiles: users see their own; admins/managers see all
CREATE POLICY "profiles_select" ON public.profiles FOR SELECT TO authenticated
  USING (id = auth.uid() OR get_user_role() IN ('system_admin','manager'));
CREATE POLICY "profiles_update_own" ON public.profiles FOR UPDATE TO authenticated
  USING (id = auth.uid() OR get_user_role() = 'system_admin');
CREATE POLICY "profiles_insert_admin" ON public.profiles FOR INSERT TO authenticated
  WITH CHECK (get_user_role() = 'system_admin');

-- Clients: all authenticated users can read; restricted writes
CREATE POLICY "clients_select" ON public.clients FOR SELECT TO authenticated USING (true);
CREATE POLICY "clients_insert" ON public.clients FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','sales_agent','fleet_coordinator'));
CREATE POLICY "clients_update" ON public.clients FOR UPDATE TO authenticated
  USING (get_user_role() IN ('system_admin','manager','sales_agent'));
CREATE POLICY "clients_delete" ON public.clients FOR DELETE TO authenticated
  USING (get_user_role() IN ('system_admin','manager'));

-- Vehicles: all can read; fleet_coordinator+ can write
CREATE POLICY "vehicles_select" ON public.vehicles FOR SELECT TO authenticated USING (true);
CREATE POLICY "vehicles_insert" ON public.vehicles FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','fleet_coordinator'));
CREATE POLICY "vehicles_update" ON public.vehicles FOR UPDATE TO authenticated
  USING (get_user_role() IN ('system_admin','manager','fleet_coordinator'));
CREATE POLICY "vehicles_delete" ON public.vehicles FOR DELETE TO authenticated
  USING (get_user_role() IN ('system_admin','manager'));

-- Drivers: all can read; fleet_coordinator+ can write
CREATE POLICY "drivers_select" ON public.drivers FOR SELECT TO authenticated USING (true);
CREATE POLICY "drivers_insert" ON public.drivers FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','fleet_coordinator'));
CREATE POLICY "drivers_update" ON public.drivers FOR UPDATE TO authenticated
  USING (get_user_role() IN ('system_admin','manager','fleet_coordinator'));
CREATE POLICY "drivers_delete" ON public.drivers FOR DELETE TO authenticated
  USING (get_user_role() IN ('system_admin','manager'));

-- Bookings: drivers see own; others see all (role-filtered in app)
CREATE POLICY "bookings_select" ON public.bookings FOR SELECT TO authenticated
  USING (get_user_role() != 'driver' OR driver_id = (SELECT d.id FROM drivers d WHERE d.email = (SELECT email FROM profiles WHERE id = auth.uid()) LIMIT 1));
CREATE POLICY "bookings_insert" ON public.bookings FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','sales_agent','fleet_coordinator'));
CREATE POLICY "bookings_update" ON public.bookings FOR UPDATE TO authenticated
  USING (get_user_role() IN ('system_admin','manager','sales_agent','fleet_coordinator'));
CREATE POLICY "bookings_delete" ON public.bookings FOR DELETE TO authenticated
  USING (get_user_role() IN ('system_admin','manager'));

-- Invoices & Payments: finance roles + admin/manager
CREATE POLICY "invoices_select" ON public.invoices FOR SELECT TO authenticated USING (true);
CREATE POLICY "invoices_insert" ON public.invoices FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','finance_officer'));
CREATE POLICY "invoices_update" ON public.invoices FOR UPDATE TO authenticated
  USING (get_user_role() IN ('system_admin','manager','finance_officer'));
CREATE POLICY "payments_select" ON public.payments FOR SELECT TO authenticated USING (true);
CREATE POLICY "payments_insert" ON public.payments FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','finance_officer'));

-- Documents: all can read own entity docs; restricted uploads
CREATE POLICY "documents_select" ON public.documents FOR SELECT TO authenticated USING (true);
CREATE POLICY "documents_insert" ON public.documents FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','fleet_coordinator','sales_agent','finance_officer'));
CREATE POLICY "documents_delete" ON public.documents FOR DELETE TO authenticated
  USING (get_user_role() IN ('system_admin','manager'));

-- Audit Logs: IMMUTABLE - read-only for admin/manager, no updates or deletes
CREATE POLICY "audit_logs_select" ON public.audit_logs FOR SELECT TO authenticated
  USING (get_user_role() IN ('system_admin','manager'));
-- NO INSERT, UPDATE, or DELETE policies - triggers handle inserts, no modifications allowed

-- Notifications: system can create; users can read their own
CREATE POLICY "notifications_select" ON public.notifications FOR SELECT TO authenticated
  USING (get_user_role() IN ('system_admin','manager') OR 
         recipient_email = (SELECT email FROM profiles WHERE id = auth.uid()));
CREATE POLICY "notifications_insert" ON public.notifications FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','sales_agent','finance_officer','fleet_coordinator'));

-- Activity Timeline: all can read; system creates
CREATE POLICY "activity_timeline_select" ON public.activity_timeline FOR SELECT TO authenticated USING (true);
-- INSERT handled by triggers only

-- Exchange Rates: all can read; admin can manage
CREATE POLICY "exchange_rates_select" ON public.exchange_rates FOR SELECT TO authenticated USING (true);
CREATE POLICY "exchange_rates_insert" ON public.exchange_rates FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','finance_officer'));

-- ─── Indexes ─────────────────────────────────────────────────
CREATE INDEX idx_bookings_client_id ON public.bookings(client_id);
CREATE INDEX idx_bookings_vehicle_id ON public.bookings(vehicle_id);
CREATE INDEX idx_bookings_driver_id ON public.bookings(driver_id);
CREATE INDEX idx_bookings_status ON public.bookings(status);
CREATE INDEX idx_bookings_pickup_datetime ON public.bookings(pickup_datetime);
CREATE INDEX idx_invoices_client_id ON public.invoices(client_id);
CREATE INDEX idx_invoices_booking_id ON public.invoices(booking_id);
CREATE INDEX idx_invoices_status ON public.invoices(status);
CREATE INDEX idx_documents_entity ON public.documents(entity_type, entity_id);
CREATE INDEX idx_audit_logs_user_id ON public.audit_logs(user_id);
CREATE INDEX idx_audit_logs_table_name ON public.audit_logs(table_name);
CREATE INDEX idx_audit_logs_timestamp ON public.audit_logs(timestamp DESC);
CREATE INDEX idx_activity_timeline_entity ON public.activity_timeline(entity_type, entity_id);
CREATE INDEX idx_activity_timeline_created_at ON public.activity_timeline(created_at DESC);
CREATE INDEX idx_notifications_status ON public.notifications(status);
CREATE INDEX idx_notifications_created_at ON public.notifications(created_at DESC);

-- ─── Insert Default Exchange Rates ───────────────────────────
INSERT INTO public.exchange_rates (from_currency, to_currency, rate) VALUES
  ('ZAR', 'USD', 0.055),
  ('ZAR', 'EUR', 0.050),
  ('ZAR', 'GBP', 0.043),
  ('ZAR', 'AED', 0.202),
  ('USD', 'ZAR', 18.18),
  ('EUR', 'ZAR', 20.00),
  ('GBP', 'ZAR', 23.26),
  ('AED', 'ZAR', 4.95);

display_content.json_block:
{"language": "sql", "code": "-- ============================================================
-- Fhdan Fleet Hub — Enhanced Schema with Audit Logs & Advanced Features
-- Run this in: Supabase Dashboard → SQL Editor → New Query
-- ============================================================

-- Enums
CREATE TYPE user_role AS ENUM ('system_admin','manager','finance_officer','sales_agent','fleet_coordinator','driver');
CREATE TYPE client_type AS ENUM ('individual','corporate','government');
CREATE TYPE client_status AS ENUM ('active','inactive','blacklisted');
CREATE TYPE currency_code AS ENUM ('ZAR','USD','EUR','GBP','AED');
CREATE TYPE tax_zone AS ENUM ('standard','exempt','foreign');
CREATE TYPE vehicle_status AS ENUM ('available','booked','maintenance','inactive');
CREATE TYPE vehicle_category AS ENUM ('sedan','suv','luxury','minibus','bus','van','pickup');
CREATE TYPE drive_mode AS ENUM ('chauffeur','self_drive','both');
CREATE TYPE fuel_type AS ENUM ('petrol','diesel','electric','hybrid');
CREATE TYPE driver_status AS ENUM ('available','on_trip','off_duty','suspended');
CREATE TYPE license_code AS ENUM ('B','C','C1','EB','PDP');
CREATE TYPE booking_status AS ENUM ('quote','pending_deposit','confirmed','active','completed','cancelled','no_show');
CREATE TYPE booking_type AS ENUM ('chauffeur','self_drive');
CREATE TYPE invoice_status AS ENUM ('draft','sent','paid','overdue','cancelled','void');
CREATE TYPE payment_method AS ENUM ('eft','cash','card','crypto','other');
CREATE TYPE entity_type AS ENUM ('client','driver','vehicle');
CREATE TYPE document_type AS ENUM ('passport','rsa_id','drivers_license','pdp','vehicle_registration','insurance','roadworthy','other');
CREATE TYPE audit_action AS ENUM ('create','update','delete','login','logout','access_denied');
CREATE TYPE notification_type AS ENUM ('booking_confirmed','payment_received','deposit_reminder','late_return','maintenance_due','high_value_booking','system_alert');
CREATE TYPE notification_status AS ENUM ('pending','sent','failed');

-- ─── Profiles (extends auth.users) ───────────────────────────
CREATE TABLE public.profiles (
  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  email TEXT NOT NULL,
  full_name TEXT NOT NULL,
  role user_role NOT NULL DEFAULT 'sales_agent',
  phone TEXT,
  avatar_url TEXT,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  last_login TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Clients ─────────────────────────────────────────────────
CREATE TABLE public.clients (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email TEXT NOT NULL,
  full_name TEXT NOT NULL,
  phone TEXT,
  id_number TEXT,
  client_type client_type NOT NULL DEFAULT 'individual',
  status client_status NOT NULL DEFAULT 'active',
  company_name TEXT,
  vat_number TEXT,
  tax_zone tax_zone NOT NULL DEFAULT 'standard',
  preferred_currency currency_code NOT NULL DEFAULT 'ZAR',
  payment_terms_days INTEGER NOT NULL DEFAULT 30,
  address TEXT,
  city TEXT,
  country TEXT NOT NULL DEFAULT 'South Africa',
  notes TEXT,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Vehicles ────────────────────────────────────────────────
CREATE TABLE public.vehicles (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  registration TEXT NOT NULL UNIQUE,
  make TEXT NOT NULL,
  model TEXT NOT NULL,
  year INTEGER NOT NULL,
  color TEXT NOT NULL,
  category vehicle_category NOT NULL,
  fuel_type fuel_type NOT NULL DEFAULT 'petrol',
  seating_capacity INTEGER NOT NULL DEFAULT 4,
  drive_modes drive_mode NOT NULL DEFAULT 'both',
  status vehicle_status NOT NULL DEFAULT 'available',
  daily_rate_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  chauffeur_rate_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  odometer_km INTEGER NOT NULL DEFAULT 0,
  last_service_date DATE,
  next_service_due_km INTEGER,
  insurance_expiry DATE,
  roadworthy_expiry DATE,
  gps_tracker_id TEXT,
  current_latitude NUMERIC(10,6),
  current_longitude NUMERIC(10,6),
  last_gps_update TIMESTAMPTZ,
  image_url TEXT,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Drivers ─────────────────────────────────────────────────
CREATE TABLE public.drivers (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  full_name TEXT NOT NULL,
  phone TEXT NOT NULL,
  email TEXT,
  id_number TEXT,
  license_code license_code NOT NULL DEFAULT 'EB',
  pdp_expiry DATE,
  status driver_status NOT NULL DEFAULT 'available',
  total_trips INTEGER NOT NULL DEFAULT 0,
  current_latitude NUMERIC(10,6),
  current_longitude NUMERIC(10,6),
  last_location_update TIMESTAMPTZ,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Exchange Rates (for multi-currency quoting) ─────────────
CREATE TABLE public.exchange_rates (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  from_currency currency_code NOT NULL,
  to_currency currency_code NOT NULL,
  rate NUMERIC(12,6) NOT NULL,
  effective_date DATE NOT NULL DEFAULT CURRENT_DATE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(from_currency, to_currency, effective_date)
);

-- ─── Bookings ────────────────────────────────────────────────
CREATE TABLE public.bookings (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  booking_reference TEXT NOT NULL UNIQUE,
  client_id UUID NOT NULL REFERENCES public.clients(id),
  vehicle_id UUID NOT NULL REFERENCES public.vehicles(id),
  driver_id UUID REFERENCES public.drivers(id),
  assigned_by UUID REFERENCES public.profiles(id),
  booking_type booking_type NOT NULL DEFAULT 'chauffeur',
  status booking_status NOT NULL DEFAULT 'quote',
  pickup_datetime TIMESTAMPTZ NOT NULL,
  dropoff_datetime TIMESTAMPTZ NOT NULL,
  pickup_location TEXT NOT NULL,
  dropoff_location TEXT NOT NULL,
  currency TEXT NOT NULL DEFAULT 'ZAR',
  exchange_rate_id UUID REFERENCES public.exchange_rates(id),
  locked_exchange_rate NUMERIC(12,6),
  subtotal_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  discount_amount NUMERIC(10,2) NOT NULL DEFAULT 0,
  deposit_amount NUMERIC(10,2) NOT NULL DEFAULT 0,
  vat_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  total_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  special_requirements TEXT,
  internal_notes TEXT,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Invoices ────────────────────────────────────────────────
CREATE TABLE public.invoices (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_number TEXT NOT NULL UNIQUE,
  booking_id UUID NOT NULL REFERENCES public.bookings(id),
  client_id UUID NOT NULL REFERENCES public.clients(id),
  status invoice_status NOT NULL DEFAULT 'draft',
  subtotal_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  vat_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  total_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  balance_due_zar NUMERIC(10,2) NOT NULL DEFAULT 0,
  payments_received NUMERIC(10,2) NOT NULL DEFAULT 0,
  issued_date DATE NOT NULL DEFAULT CURRENT_DATE,
  due_date DATE NOT NULL,
  paid_date DATE,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Payments ────────────────────────────────────────────────
CREATE TABLE public.payments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  invoice_id UUID NOT NULL REFERENCES public.invoices(id),
  amount_zar NUMERIC(10,2) NOT NULL,
  payment_method payment_method NOT NULL DEFAULT 'eft',
  payment_date DATE NOT NULL DEFAULT CURRENT_DATE,
  reference TEXT,
  notes TEXT,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Documents (with encryption metadata) ────────────────────
CREATE TABLE public.documents (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  entity_type entity_type NOT NULL,
  entity_id UUID NOT NULL,
  document_type document_type NOT NULL,
  file_name TEXT NOT NULL,
  file_path TEXT,
  file_size INTEGER NOT NULL DEFAULT 0,
  is_encrypted BOOLEAN NOT NULL DEFAULT TRUE,
  encryption_key_id TEXT,
  expiry_date DATE,
  uploaded_by UUID NOT NULL REFERENCES public.profiles(id),
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── IMMUTABLE Audit Log ──────────────────────────────────────
-- This table has NO UPDATE or DELETE policies - records are permanent
CREATE TABLE public.audit_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES public.profiles(id),
  user_email TEXT NOT NULL,
  user_role user_role,
  action audit_action NOT NULL,
  table_name TEXT NOT NULL,
  record_id UUID,
  old_data JSONB,
  new_data JSONB,
  ip_address TEXT,
  user_agent TEXT,
  timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Notifications ────────────────────────────────────────────
CREATE TABLE public.notifications (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  recipient_email TEXT NOT NULL,
  recipient_phone TEXT,
  notification_type notification_type NOT NULL,
  subject TEXT NOT NULL,
  message TEXT NOT NULL,
  status notification_status NOT NULL DEFAULT 'pending',
  related_booking_id UUID REFERENCES public.bookings(id),
  related_invoice_id UUID REFERENCES public.invoices(id),
  sent_at TIMESTAMPTZ,
  error_message TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Activity Timeline (for 360° history view) ───────────────
CREATE TABLE public.activity_timeline (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  entity_type entity_type NOT NULL,
  entity_id UUID NOT NULL,
  activity_type TEXT NOT NULL,
  description TEXT NOT NULL,
  metadata JSONB,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- ─── Auto-update updated_at ──────────────────────────────────
CREATE OR REPLACE FUNCTION update_updated_at()
RETURNS TRIGGER AS $$
BEGIN NEW.updated_at = NOW(); RETURN NEW; END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_profiles_updated_at BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER trg_clients_updated_at BEFORE UPDATE ON public.clients FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER trg_vehicles_updated_at BEFORE UPDATE ON public.vehicles FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER trg_drivers_updated_at BEFORE UPDATE ON public.drivers FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER trg_bookings_updated_at BEFORE UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER trg_invoices_updated_at BEFORE UPDATE ON public.invoices FOR EACH ROW EXECUTE FUNCTION update_updated_at();

-- ─── Auto-create profile on signup ──────────────────────────
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.profiles (id, email, full_name, role)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', split_part(NEW.email, '@', 1)),
    COALESCE((NEW.raw_user_meta_data->>'role')::user_role, 'sales_agent')
  );
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- ─── Audit Log Trigger Function ──────────────────────────────
CREATE OR REPLACE FUNCTION public.log_audit()
RETURNS TRIGGER AS $$
DECLARE
  current_user_email TEXT;
  current_user_role user_role;
  action_type audit_action;
BEGIN
  -- Get current user info
  SELECT email, role INTO current_user_email, current_user_role 
  FROM public.profiles WHERE id = auth.uid();

  -- Determine action type
  IF TG_OP = 'INSERT' THEN
    action_type := 'create';
  ELSIF TG_OP = 'UPDATE' THEN
    action_type := 'update';
  ELSIF TG_OP = 'DELETE' THEN
    action_type := 'delete';
  END IF;

  -- Insert audit log
  INSERT INTO public.audit_logs (
    user_id, user_email, user_role, action, table_name, 
    record_id, old_data, new_data, timestamp
  ) VALUES (
    auth.uid(),
    COALESCE(current_user_email, 'system'),
    current_user_role,
    action_type,
    TG_TABLE_NAME,
    COALESCE(NEW.id, OLD.id),
    CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN row_to_json(OLD) ELSE NULL END,
    CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN row_to_json(NEW) ELSE NULL END,
    NOW()
  );

  RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ─── Apply Audit Triggers to All Tables ──────────────────────
CREATE TRIGGER audit_clients AFTER INSERT OR UPDATE OR DELETE ON public.clients
  FOR EACH ROW EXECUTE FUNCTION public.log_audit();

CREATE TRIGGER audit_vehicles AFTER INSERT OR UPDATE OR DELETE ON public.vehicles
  FOR EACH ROW EXECUTE FUNCTION public.log_audit();

CREATE TRIGGER audit_drivers AFTER INSERT OR UPDATE OR DELETE ON public.drivers
  FOR EACH ROW EXECUTE FUNCTION public.log_audit();

CREATE TRIGGER audit_bookings AFTER INSERT OR UPDATE OR DELETE ON public.bookings
  FOR EACH ROW EXECUTE FUNCTION public.log_audit();

CREATE TRIGGER audit_invoices AFTER INSERT OR UPDATE OR DELETE ON public.invoices
  FOR EACH ROW EXECUTE FUNCTION public.log_audit();

CREATE TRIGGER audit_payments AFTER INSERT OR UPDATE OR DELETE ON public.payments
  FOR EACH ROW EXECUTE FUNCTION public.log_audit();

CREATE TRIGGER audit_documents AFTER INSERT OR UPDATE OR DELETE ON public.documents
  FOR EACH ROW EXECUTE FUNCTION public.log_audit();

-- ─── Activity Timeline Triggers ──────────────────────────────
CREATE OR REPLACE FUNCTION public.log_activity()
RETURNS TRIGGER AS $$
DECLARE
  activity_desc TEXT;
  entity_type_val entity_type;
BEGIN
  -- Determine entity type and description based on table
  IF TG_TABLE_NAME = 'bookings' THEN
    entity_type_val := 'client';
    IF TG_OP = 'INSERT' THEN
      activity_desc := 'New booking created: ' || NEW.booking_reference;
    ELSIF TG_OP = 'UPDATE' AND OLD.status != NEW.status THEN
      activity_desc := 'Booking status changed from ' || OLD.status || ' to ' || NEW.status;
    END IF;

    IF activity_desc IS NOT NULL THEN
      INSERT INTO public.activity_timeline (entity_type, entity_id, activity_type, description, metadata, created_by)
      VALUES (entity_type_val, NEW.client_id, 'booking', activity_desc, row_to_json(NEW), auth.uid());
    END IF;

  ELSIF TG_TABLE_NAME = 'invoices' AND TG_OP = 'INSERT' THEN
    INSERT INTO public.activity_timeline (entity_type, entity_id, activity_type, description, metadata, created_by)
    VALUES ('client', NEW.client_id, 'invoice', 'Invoice generated: ' || NEW.invoice_number, row_to_json(NEW), auth.uid());

  ELSIF TG_TABLE_NAME = 'payments' AND TG_OP = 'INSERT' THEN
    INSERT INTO public.activity_timeline (entity_type, entity_id, activity_type, description, metadata, created_by)
    VALUES ('client', (SELECT client_id FROM public.invoices WHERE id = NEW.invoice_id), 'payment', 
            'Payment received: R' || NEW.amount_zar, row_to_json(NEW), auth.uid());
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE TRIGGER activity_bookings AFTER INSERT OR UPDATE ON public.bookings
  FOR EACH ROW EXECUTE FUNCTION public.log_activity();

CREATE TRIGGER activity_invoices AFTER INSERT ON public.invoices
  FOR EACH ROW EXECUTE FUNCTION public.log_activity();

CREATE TRIGGER activity_payments AFTER INSERT ON public.payments
  FOR EACH ROW EXECUTE FUNCTION public.log_activity();

-- ─── Helper: get current user role ──────────────────────────
CREATE OR REPLACE FUNCTION public.get_user_role()
RETURNS user_role AS $$
  SELECT role FROM public.profiles WHERE id = auth.uid()
$$ LANGUAGE SQL SECURITY DEFINER STABLE;

-- ─── Enable RLS ──────────────────────────────────────────────
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.clients ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vehicles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.drivers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.bookings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.activity_timeline ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.exchange_rates ENABLE ROW LEVEL SECURITY;

-- ─── RLS Policies ────────────────────────────────────────────

-- Profiles: users see their own; admins/managers see all
CREATE POLICY "profiles_select" ON public.profiles FOR SELECT TO authenticated
  USING (id = auth.uid() OR get_user_role() IN ('system_admin','manager'));
CREATE POLICY "profiles_update_own" ON public.profiles FOR UPDATE TO authenticated
  USING (id = auth.uid() OR get_user_role() = 'system_admin');
CREATE POLICY "profiles_insert_admin" ON public.profiles FOR INSERT TO authenticated
  WITH CHECK (get_user_role() = 'system_admin');

-- Clients: all authenticated users can read; restricted writes
CREATE POLICY "clients_select" ON public.clients FOR SELECT TO authenticated USING (true);
CREATE POLICY "clients_insert" ON public.clients FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','sales_agent','fleet_coordinator'));
CREATE POLICY "clients_update" ON public.clients FOR UPDATE TO authenticated
  USING (get_user_role() IN ('system_admin','manager','sales_agent'));
CREATE POLICY "clients_delete" ON public.clients FOR DELETE TO authenticated
  USING (get_user_role() IN ('system_admin','manager'));

-- Vehicles: all can read; fleet_coordinator+ can write
CREATE POLICY "vehicles_select" ON public.vehicles FOR SELECT TO authenticated USING (true);
CREATE POLICY "vehicles_insert" ON public.vehicles FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','fleet_coordinator'));
CREATE POLICY "vehicles_update" ON public.vehicles FOR UPDATE TO authenticated
  USING (get_user_role() IN ('system_admin','manager','fleet_coordinator'));
CREATE POLICY "vehicles_delete" ON public.vehicles FOR DELETE TO authenticated
  USING (get_user_role() IN ('system_admin','manager'));

-- Drivers: all can read; fleet_coordinator+ can write
CREATE POLICY "drivers_select" ON public.drivers FOR SELECT TO authenticated USING (true);
CREATE POLICY "drivers_insert" ON public.drivers FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','fleet_coordinator'));
CREATE POLICY "drivers_update" ON public.drivers FOR UPDATE TO authenticated
  USING (get_user_role() IN ('system_admin','manager','fleet_coordinator'));
CREATE POLICY "drivers_delete" ON public.drivers FOR DELETE TO authenticated
  USING (get_user_role() IN ('system_admin','manager'));

-- Bookings: drivers see own; others see all (role-filtered in app)
CREATE POLICY "bookings_select" ON public.bookings FOR SELECT TO authenticated
  USING (get_user_role() != 'driver' OR driver_id = (SELECT d.id FROM drivers d WHERE d.email = (SELECT email FROM profiles WHERE id = auth.uid()) LIMIT 1));
CREATE POLICY "bookings_insert" ON public.bookings FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','sales_agent','fleet_coordinator'));
CREATE POLICY "bookings_update" ON public.bookings FOR UPDATE TO authenticated
  USING (get_user_role() IN ('system_admin','manager','sales_agent','fleet_coordinator'));
CREATE POLICY "bookings_delete" ON public.bookings FOR DELETE TO authenticated
  USING (get_user_role() IN ('system_admin','manager'));

-- Invoices & Payments: finance roles + admin/manager
CREATE POLICY "invoices_select" ON public.invoices FOR SELECT TO authenticated USING (true);
CREATE POLICY "invoices_insert" ON public.invoices FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','finance_officer'));
CREATE POLICY "invoices_update" ON public.invoices FOR UPDATE TO authenticated
  USING (get_user_role() IN ('system_admin','manager','finance_officer'));
CREATE POLICY "payments_select" ON public.payments FOR SELECT TO authenticated USING (true);
CREATE POLICY "payments_insert" ON public.payments FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','finance_officer'));

-- Documents: all can read own entity docs; restricted uploads
CREATE POLICY "documents_select" ON public.documents FOR SELECT TO authenticated USING (true);
CREATE POLICY "documents_insert" ON public.documents FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','fleet_coordinator','sales_agent','finance_officer'));
CREATE POLICY "documents_delete" ON public.documents FOR DELETE TO authenticated
  USING (get_user_role() IN ('system_admin','manager'));

-- Audit Logs: IMMUTABLE - read-only for admin/manager, no updates or deletes
CREATE POLICY "audit_logs_select" ON public.audit_logs FOR SELECT TO authenticated
  USING (get_user_role() IN ('system_admin','manager'));
-- NO INSERT, UPDATE, or DELETE policies - triggers handle inserts, no modifications allowed

-- Notifications: system can create; users can read their own
CREATE POLICY "notifications_select" ON public.notifications FOR SELECT TO authenticated
  USING (get_user_role() IN ('system_admin','manager') OR 
         recipient_email = (SELECT email FROM profiles WHERE id = auth.uid()));
CREATE POLICY "notifications_insert" ON public.notifications FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','sales_agent','finance_officer','fleet_coordinator'));

-- Activity Timeline: all can read; system creates
CREATE POLICY "activity_timeline_select" ON public.activity_timeline FOR SELECT TO authenticated USING (true);
-- INSERT handled by triggers only

-- Exchange Rates: all can read; admin can manage
CREATE POLICY "exchange_rates_select" ON public.exchange_rates FOR SELECT TO authenticated USING (true);
CREATE POLICY "exchange_rates_insert" ON public.exchange_rates FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('system_admin','manager','finance_officer'));

-- ─── Indexes ─────────────────────────────────────────────────
CREATE INDEX idx_bookings_client_id ON public.bookings(client_id);
CREATE INDEX idx_bookings_vehicle_id ON public.bookings(vehicle_id);
CREATE INDEX idx_bookings_driver_id ON public.bookings(driver_id);
CREATE INDEX idx_bookings_status ON public.bookings(status);
CREATE INDEX idx_bookings_pickup_datetime ON public.bookings(pickup_datetime);
CREATE INDEX idx_invoices_client_id ON public.invoices(client_id);
CREATE INDEX idx_invoices_booking_id ON public.invoices(booking_id);
CREATE INDEX idx_invoices_status ON public.invoices(status);
CREATE INDEX idx_documents_entity ON public.documents(entity_type, entity_id);
CREATE INDEX idx_audit_logs_user_id ON public.audit_logs(user_id);
CREATE INDEX idx_audit_logs_table_name ON public.audit_logs(table_name);
CREATE INDEX idx_audit_logs_timestamp ON public.audit_logs(timestamp DESC);
CREATE INDEX idx_activity_timeline_entity ON public.activity_timeline(entity_type, entity_id);
CREATE INDEX idx_activity_timeline_created_at ON public.activity_timeline(created_at DESC);
CREATE INDEX idx_notifications_status ON public.notifications(status);
CREATE INDEX idx_notifications_created_at ON public.notifications(created_at DESC);

-- ─── Insert Default Exchange Rates ───────────────────────────
INSERT INTO public.exchange_rates (from_currency, to_currency, rate) VALUES
  ('ZAR', 'USD', 0.055),
  ('ZAR', 'EUR', 0.050),
  ('ZAR', 'GBP', 0.043),
  ('ZAR', 'AED', 0.202),
  ('USD', 'ZAR', 18.18),
  ('EUR', 'ZAR', 20.00),
  ('GBP', 'ZAR', 23.26),
  ('AED', 'ZAR', 4.95);
